from __future__ import annotations

import csv
import json
import re
from collections import defaultdict
from datetime import date, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from pathlib import Path


DATASET = Path("/app/dataset")


def _read_csv(name: str) -> list[dict[str, str]]:
    with (DATASET / name).open(encoding="utf-8", newline="") as file:
        return list(csv.DictReader(file))


def _billing_start(day: date, payday_weekday: int) -> date:
    """Return the latest first payday weekday of a calendar month."""
    first = day.replace(day=1)
    start = first + timedelta(days=(payday_weekday - first.weekday()) % 7)
    if day >= start:
        return start

    previous_month_last_day = first - timedelta(days=1)
    first = previous_month_last_day.replace(day=1)
    return first + timedelta(days=(payday_weekday - first.weekday()) % 7)


def answer() -> dict[str, list[int]]:
    employee_rows = _read_csv("employees.csv")
    task_rows = _read_csv("tasks.csv")
    timesheet_rows = _read_csv("timesheet.csv")

    rates: dict[str, Decimal] = {}
    for row in employee_rows:
        pesel = row["PESEL"].strip()
        try:
            rate = Decimal(row["hourly_rate"])
        except InvalidOperation:
            continue
        if len(pesel) == 11 and pesel.isdigit() and rate >= 0:
            rates[pesel] = rate

    task_pay: dict[int, Decimal] = {}
    for row in task_rows:
        try:
            task_id = int(row["task_id"])
            pay = Decimal(row["pay_per_completion"])
        except (ValueError, InvalidOperation):
            continue
        if pay >= 0:
            task_pay[task_id] = pay

    valid_dated_rows: list[tuple[date, dict[str, str]]] = []
    for row in timesheet_rows:
        try:
            work_date = date.fromisoformat(row["date"])
        except (KeyError, ValueError):
            # Impossible dates such as April 31 cannot be repaired uniquely.
            continue
        valid_dated_rows.append((work_date, row))

    if not valid_dated_rows:
        return {pesel: [] for pesel in sorted(rates)}

    earliest_date = min(work_date for work_date, _ in valid_dated_rows)
    payday_weekday = earliest_date.weekday()

    totals: defaultdict[tuple[str, date], Decimal] = defaultdict(Decimal)
    periods: set[date] = set()
    seen_rows: set[tuple[str, ...]] = set()

    for work_date, row in valid_dated_rows:
        pesel = row["employee_id"].strip()
        if pesel not in rates:
            # There is no reliable employee record/rate for an unknown PESEL.
            continue

        # Row IDs differ on the exact duplicate records, so exclude the ID from
        # the duplicate key and count the underlying work record only once.
        duplicate_key = tuple(
            row[column]
            for column in (
                "date",
                "hours_worked",
                "performed_tasks",
                "employee_id",
                "facility_id",
                "salary_amount",
                "bonus",
            )
        )
        if duplicate_key in seen_rows:
            continue
        seen_rows.add(duplicate_key)

        try:
            hours = Decimal(row["hours_worked"])
        except InvalidOperation:
            continue
        if not hours.is_finite() or hours < 0 or hours > 24:
            continue

        period = _billing_start(work_date, payday_weekday)
        periods.add(period)

        # A missing bracket is repairable. Unknown task IDs are not, and are
        # therefore omitted instead of trusting the inconsistent bonus column.
        task_ids = (int(value) for value in re.findall(r"\d+", row["performed_tasks"]))
        bonus = sum((task_pay[task_id] for task_id in task_ids if task_id in task_pay), Decimal(0))
        totals[pesel, period] += hours * rates[pesel] + bonus

    ordered_periods = sorted(periods)
    result: dict[str, list[int]] = {}
    for pesel in sorted(rates):
        result[pesel] = [
            int(totals[pesel, period].quantize(Decimal("1"), rounding=ROUND_HALF_UP))
            for period in ordered_periods
        ]
    return result


if __name__ == "__main__":
    with Path("/app/answer.json").open("w", encoding="utf-8") as file:
        json.dump(answer(), file, default=list)

